/**
|--------------------------------------------------
| Npm imports
|--------------------------------------------------
*/
import clsx from 'clsx';
import React from 'react';
import { Svg, Path, Rect } from 'react-native-svg';
import { useQueryClient } from '@tanstack/react-query';
import { View, Pressable, ScrollView, RefreshControl } from 'react-native';

/**
 |--------------------------------------------------
 | Custom imports
 |--------------------------------------------------
 */
import MPText from '@src/components/MPText';
import HeaderWrapper from '@src/components/Header';
import ScreenWrapper from '@src/components/Wrapper';
import CustomRefreshControl from '@src/components/CustomRefreshControl';
import { useGetNotifications, useMarkNotificationAsRead } from '@services/user.services';

export default function NotificationScreen() {
	const queryClient = useQueryClient();

	/**
    |--------------------------------------------------
    | Api calls
    |--------------------------------------------------
    */
	const { mutate, isPending: isReading } = useMarkNotificationAsRead();
	const { data, fetchNextPage, hasNextPage, isFetchingNextPage, isPending, isLoading } = useGetNotifications({
		limit: 20,
	});
	const notifications = data?.pages.flatMap((page) => page.notifications) ?? [];

	/**
    |--------------------------------------------------
    | Rendered View
    |--------------------------------------------------
    */
	return (
		<ScreenWrapper>
			<HeaderWrapper title="Notifications" center />

			{/**
            |--------------------------------------------------
            | First row
            |--------------------------------------------------
            */}
			<View className={clsx('mb-3', notifications.length === 0 ? '!hidden' : '')}>
				<Pressable className="ml-auto" onPress={() => mutate({})}>
					<MPText weight="semibold" className="text-[13px] text-[#FF6A00]">
						Mark all as read
					</MPText>
				</Pressable>
			</View>

			{/**
            |--------------------------------------------------
            | Main content
            |--------------------------------------------------
            */}
			<ScrollView
				refreshControl={
					<RefreshControl
						refreshing={false}
						tintColor="transparent"
						colors={['transparent']}
						onRefresh={() => {
							queryClient.invalidateQueries({ queryKey: ['user_notifications'] });
						}}
					/>
				}
				showsVerticalScrollIndicator={false}
				onScroll={async ({ nativeEvent }) => {
					const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
					const isScrolledToEnd = layoutMeasurement.height + contentOffset.y >= contentSize.height - 10;

					/**
					|--------------------------------------------------
					| If the user has scrolled to the end
					|--------------------------------------------------
					*/
					if (isScrolledToEnd && hasNextPage && !isFetchingNextPage) {
						fetchNextPage();
					}
				}}
			>
				<View className="gap-6">
					{(!isLoading || !isPending || !isFetchingNextPage || !isReading) &&
						notifications?.map((notification) => (
							<Pressable
								key={(notification as any)?._id}
								onPress={() => mutate({ id: (notification as any)?._id })}
								className="flex-row items-start rounded-2xl border-[0.5px] border-[#EEEEEE] p-4"
							>
								{/**
                                |--------------------------------------------------
                                | Icon
                                |--------------------------------------------------
                                */}
								<View>{IconTypes[notification.type as keyof typeof IconTypes]}</View>

								{/**
                                |--------------------------------------------------
                                | Title and message
                                |--------------------------------------------------
                                */}
								<View className="ml-4 flex-1">
									<View className="mb-1 flex-row items-center gap-2">
										<MPText weight="semibold" className="text-[15px]">
											{notification?.metadata?.reason}
										</MPText>

										{/**
                                        |--------------------------------------------------
                                        | Dot
                                        |--------------------------------------------------
                                        */}
										{notification.isRead ? null : (
											<Svg width={8} height={8} viewBox="0 0 24 24">
												<Path
													d="M12 2C6.47 2 2 6.47 2 12s4.47 10 10 10 10-4.47 10-10S17.53 2 12 2"
													fill="red"
												/>
											</Svg>
										)}
									</View>
									<MPText
										weight="medium"
										style={{ lineHeight: 15 }}
										className="flex-1 text-[13px] text-[#484848]"
									>
										{notification.message}
									</MPText>
								</View>
							</Pressable>
						))}

					{/**
                    |--------------------------------------------------
                    | Loading
                    |--------------------------------------------------
                    */}
					{(isLoading || isPending || isFetchingNextPage || isReading) && (
						<CustomRefreshControl refreshing={isLoading || isPending || isFetchingNextPage} />
					)}

					{/**
					|--------------------------------------------------
					| If there are no more notifications
					|--------------------------------------------------
					*/}
					{(!hasNextPage || !isFetchingNextPage || !isLoading || !isPending || !isReading) && (
						<MPText weight="medium" className="self-center text-[15px] text-[#FF6A00]">
							No more notifications
						</MPText>
					)}
				</View>
			</ScrollView>
		</ScreenWrapper>
	);
}

